{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "A close coumarin/xanthone analogue with a chlorophenyl and N-methylpiperazine substituent showed a brain-to-plasma ratio of 31.6 in mice and was labeled high permeability, directly supporting CNS access for the query's coumarin/chlorobenzyl-piperidine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "[11C]MC113, a methoxy-substituted tetrahydroisoquinoline with a benzylpiperidine-like motif, showed high brain uptake by microPET in mice, supporting the CNS penetration of the query's methoxyaryl and benzylic amine features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "[11C]MC80, a dimethoxy-tetrahydroisoquinoline with a naphthylmethyl substituent, showed high initial brain uptake in mouse biodistribution studies, supporting the query's lipophilic methoxy and benzylic amine combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A 4-methyl-7-(N-methyltetrahydropyridinyloxy)coumarin freely crossed the BBB in rodents and non-human primates after IV injection, directly supporting the coumarin-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "SR-17018, a dichlorophenyl/benzylpiperidine heterocycle, crosses the BBB after systemic administration, supporting the query's chlorobenzylpiperidine motif as CNS-permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A 4-methoxybenzamide with a 1-benzyl-4-piperidinyl amide showed significant and lasting high brain uptake in mice, supporting the query's methoxyaryl and benzylpiperidine combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "[11C]QCA, a polar quinoline carboxamide with a succinimide group, showed limited brain uptake in mice, but this poor-penetration phenotype is less transferable because the query lacks the primary amide and succinimide polar liabilities.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "PET in rats showed practically no brain influx for [11C]QCA, reinforcing the poor CNS access of that polar quinoline carboxamide scaffold, which is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query's coumarin/chlorobenzylpiperidine scaffold aligns with multiple close analogues showing high brain uptake or free BBB crossing, while the few poor-penetration analogues are more polar and less similar; the overall evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule",
    "P-gp/BCRP efflux liability not directly assessed for the query",
    "Human CNS exposure data unavailable for the exact query"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

